let d = msg.payload;

// Pastikan payload berupa object
if (!d || typeof d !== "object") {
    node.warn("Payload bukan object");
    return null;
}

// Pastikan field utama tersedia
if (
    d.ph === undefined ||
    d.tds === undefined ||
    d.turbidity === undefined
) {
    node.warn("Data pH/TDS/Turbidity tidak lengkap");
    return null;
}

// Konversi menjadi angka
let ph = Number(d.ph);
let tds = Number(d.tds);
let turbidity = Number(d.turbidity);

// Pastikan angka valid
if (
    !Number.isFinite(ph) ||
    !Number.isFinite(tds) ||
    !Number.isFinite(turbidity)
) {
    node.warn("Data sensor bukan angka valid");
    return null;
}

// Validasi range dasar
if (ph < 0 || ph > 14) {
    node.warn("Nilai pH di luar range");
    return null;
}

if (tds < 0) {
    node.warn("Nilai TDS negatif");
    return null;
}

if (turbidity < 0) {
    node.warn("Nilai turbidity negatif");
    return null;
}

// =======================
// Timestamp WITA (UTC+8)
// =======================
const now = new Date();
const witaTime = new Date(now.getTime() + (8 * 60 * 60 * 1000))
    .toISOString()
    .replace("Z", "+08:00");

// Data yang diteruskan
msg.payload = {
    device_id: "AM-BORIKAMASE-01",

    timestamp: witaTime,

    ph_raw: ph,
    tds_raw: tds,
    turbidity_raw: turbidity,

    sensor_status: d.sensor_status || "UNKNOWN"
};

return msg;

let d = msg.payload;

// Ambil state Kalman dari context
let state = context.get("state");
let P = context.get("P");

// Inisialisasi pertama
if (!state) {
    state = {
        ph: d.ph_raw,
        tds: d.tds_raw,
        turbidity: d.turbidity_raw
    };
}

if (!P) {
    P = {
        ph: 1,
        tds: 1,
        turbidity: 1
    };
}

// Process Noise
const Q = {
    ph: 0.01,
    tds: 10,
    turbidity: 0.1
};

// Measurement Noise
const R = {
    ph: 0.1,
    tds: 20,
    turbidity: 1
};

function kalman(measurement, key) {

    // Prediction
    P[key] = P[key] + Q[key];

    // Kalman Gain
    let K = P[key] / (P[key] + R[key]);

    // Update estimation
    state[key] =
        state[key] + K * (measurement - state[key]);

    // Update covariance
    P[key] =
        (1 - K) * P[key];

    return state[key];
}

// Proses masing-masing sensor
let phFiltered =
    kalman(d.ph_raw, "ph");

let tdsFiltered =
    kalman(d.tds_raw, "tds");

let turbidityFiltered =
    kalman(d.turbidity_raw, "turbidity");

// Simpan state
context.set("state", state);
context.set("P", P);

// Tambahkan hasil filter
msg.payload.ph_filtered =
    Number(phFiltered.toFixed(2));

msg.payload.tds_filtered =
    Number(tdsFiltered.toFixed(2));

msg.payload.turbidity_filtered =
    Number(turbidityFiltered.toFixed(2));

return msg;

