        return null;
    }

    const d = new Date(
        dateStr + "T00:00:00+08:00"
    );

    if (isNaN(d.getTime())) {
        return null;
    }

    const parts = new Intl.DateTimeFormat(
        "en-CA",
        {
            timeZone: "Asia/Makassar",
            year: "numeric",
            month: "2-digit",
            day: "2-digit"
        }
    ).formatToParts(d);

    const year = parts.find(
        function (x) {
            return x.type === "year";
        }
    ).value;

    const month = parts.find(
        function (x) {
            return x.type === "month";
        }
    ).value;

    const day = parts.find(
        function (x) {
            return x.type === "day";
        }
    ).value;

    const back =
        year + "-" +
        month + "-" +
        day;

    return back === dateStr ? d : null;
}


// ============================================================
// SESSION
// Timestamp MySQL sudah WITA,
// jadi langsung gunakan HOUR(timestamp).
// ============================================================

function sessionCaseSql(col) {

    const hour = "HOUR(" + col + ")";

    return "CASE " +
        CFG.sessions.map(function (s) {

            return "WHEN " +
                hour +
                " >= " +
                s.startHour +
                " AND " +
                hour +
                " < " +
                s.endHour +
                " THEN '" +
                s.name +
                "'";

        }).join(" ") +
        " ELSE '" +
        CFG.outsideSessionLabel +
        "' END";
}


// ============================================================
// READING COLUMNS
// Timestamp dikirim sebagai:
// 2026-09-29T10:32:39+08:00
// ============================================================

function readingColumns() {

    return (
        "id, " +
        "device_id, " +

        "DATE_FORMAT(" +
        "timestamp, " +
        "'%Y-%m-%dT%H:%i:%s+08:00'" +
        ") AS timestamp, " +

        "CAST(ph_raw AS DOUBLE) AS ph_raw, " +
        "CAST(ph_filtered AS DOUBLE) AS ph_filtered, " +

        "CAST(tds_raw AS DOUBLE) AS tds_raw, " +
        "CAST(tds_filtered AS DOUBLE) AS tds_filtered, " +

        "CAST(turbidity_raw AS DOUBLE) AS turbidity_raw, " +
        "CAST(turbidity_filtered AS DOUBLE) AS turbidity_filtered, " +

        "sensor_status, " +
        "water_quality, " +

        "(" +
        sessionCaseSql("timestamp") +
        ") AS session"
    );
}


// ============================================================
// QUERY FILTERS
// ============================================================

function parseFilters(q) {

    q = q || {};

    const where = [];
    const params = [];
    const applied = {};

    const from = q.from
        ? String(q.from)
        : null;

    const to = q.to
        ? String(q.to)
        : null;


    // --------------------------------------------------------
    // VALIDASI TANGGAL
    // --------------------------------------------------------

    if (from && !witaMidnight(from)) {

        return {
            error:
                "Tanggal awal tidak valid " +
                "(format YYYY-MM-DD)."
        };
    }

    if (to && !witaMidnight(to)) {

        return {
            error:
                "Tanggal akhir tidak valid " +
                "(format YYYY-MM-DD)."
        };
    }

    if (from && to && from > to) {

        return {
            error:
                "Tanggal awal tidak boleh setelah tanggal akhir."
        };
    }


    // --------------------------------------------------------
    // FROM
    // --------------------------------------------------------

    if (from) {

        where.push(
            "timestamp >= ?"
        );

        params.push(
            from + " 00:00:00"
        );

        applied.from = from;
    }


    // --------------------------------------------------------
    // TO
    // --------------------------------------------------------

    if (to) {

        const nextDay = new Date(
            to + "T00:00:00+08:00"
        );

        nextDay.setDate(
            nextDay.getDate() + 1
        );


        const parts = new Intl.DateTimeFormat(
            "en-CA",
            {
                timeZone: "Asia/Makassar",
                year: "numeric",
                month: "2-digit",
                day: "2-digit"
            }
        ).formatToParts(nextDay);


        const yyyy = parts.find(
            function (x) {
                return x.type === "year";
            }
        ).value;

        const mm = parts.find(
            function (x) {
                return x.type === "month";
            }
        ).value;

        const dd = parts.find(
            function (x) {
                return x.type === "day";
            }
        ).value;


        where.push(
            "timestamp < ?"
        );

        params.push(
            yyyy +
            "-" +
            mm +
            "-" +
            dd +
            " 00:00:00"
        );

        applied.to = to;
    }


    // --------------------------------------------------------
    // SESSION FILTER
    // --------------------------------------------------------

    if (
        q.session &&
        q.session !== "all"
    ) {

        const names =
            CFG.sessions
                .map(function (s) {
                    return s.name;
                })
                .concat(
                    CFG.outsideSessionLabel
                );


        if (
            names.indexOf(q.session) === -1
        ) {

            return {
                error:
                    "Sesi tidak dikenal."
            };
        }


        where.push(
            "(" +
            sessionCaseSql("timestamp") +
            ") = ?"
        );

        params.push(
            q.session
        );

        applied.session =
            q.session;
    }


    // --------------------------------------------------------
    // QUALITY FILTER
    // --------------------------------------------------------

    if (
        q.quality &&
        q.quality !== "all"
    ) {

        if (
            [
                "GOOD",
                "WARNING",
                "DANGER"
            ].indexOf(q.quality) === -1
        ) {

            return {
                error:
                    "Kategori kualitas tidak dikenal."
            };
        }


        where.push(
            "water_quality = ?"
        );

        params.push(
            q.quality
        );

        applied.quality =
            q.quality;
    }


    // --------------------------------------------------------
    // SEARCH
    // --------------------------------------------------------

    const search =
        typeof q.search === "string"
            ? q.search
                .trim()
                .slice(0, 50)
            : "";


    if (search) {

        const like =
            "%" +
            search.replace(
                /[\\%_]/g,
                function (c) {
                    return "\\" + c;
                }
            ) +
            "%";


        where.push(
            "(" +

            "DATE_FORMAT(" +
            "timestamp, " +
            "'%Y-%m-%d %H:%i:%s'" +
            ") LIKE ?" +

            " OR sensor_status LIKE ?" +

            " OR water_quality LIKE ?" +

            " OR (" +
            sessionCaseSql("timestamp") +
            ") LIKE ?" +

            ")"
        );


        params.push(
            like,
            like,
            like,
            like
        );


        applied.search =
            search;
    }


    return {

        where:
            where.length
                ? "WHERE " +
                  where.join(" AND ")
                : "",

        params:
            params,

        applied:
            applied
    };
}


// ============================================================
// INTEGER PARAMETER
// ============================================================

function intParam(
    value,
    fallback,
    min,
    max
) {

    const n =
        parseInt(
            value,
            10
        );

    if (!Number.isFinite(n)) {
        return fallback;
    }

    return Math.min(
        max,
        Math.max(
            min,
            n
        )
    );
}


// ============================================================
// NUMBER OR NULL
// ============================================================

function numOrNull(v) {

    if (
        v === null ||
        v === undefined
    ) {
        return null;
    }

    const n =
        Number(v);

    return Number.isFinite(n)
        ? n
        : null;
}


