    };
}


// ============================================================
// SYSTEM STARTUP CHECK
// ============================================================

function notReady(
    respondIndex
) {

    const out =
        new Array(
            node.outputCount
        ).fill(null);

    out[respondIndex] =
        fail(
            msg,
            503,
