}


// ============================================================
// GET /api/water/history
//
// Mengambil 500 data terbaru.
// ============================================================

if (!CFG) {
    return notReady(1);
}


msg.topic =
    "SELECT " +
    readingColumns() +
    " FROM water_quality " +
    "ORDER BY timestamp DESC, id DESC " +
    "LIMIT 500";


msg.payload = [];


return [msg, null];

msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = {
    success: true,
    data: msg.payload
};

return msg;

// Counts every MQTT message on the sensor topic (valid or not). Together with
// "Track valid reading" this gives the number of rejected payloads.
const rt = global.get("aquasenseRuntime") || {};
rt.messagesReceived = (rt.messagesReceived || 0) + 1;
rt.lastMqttAt = Date.now();
global.set("aquasenseRuntime", rt);
return null;

// A payload passed "Validation Data" (complete, numeric, physically possible).
const rt = global.get("aquasenseRuntime") || {};
rt.validReadings = (rt.validReadings || 0) + 1;
rt.lastValidAt = Date.now();
global.set("aquasenseRuntime", rt);
return null;

// Records the status events of the MQTT-in, WebSocket-out and Telegram
// sender nodes (as shown under each node in the editor).
const rt = global.get("aquasenseRuntime") || {};
const s = msg.status || {};
const text = String(s.text || "");
const source = msg.status && msg.status.source ? msg.status.source.id : null;
const now = Date.now();

if (source === "dc3029e55ab70b93") {
    // mqtt in: "connected" / "disconnected" / "connecting"
    const t = text.toLowerCase();
    rt.mqttStatus = /disconnected/.test(t) ? "disconnected" : /connecting/.test(t) ? "connecting" : /connected/.test(t) ? "connected" : (t || "unknown");
    rt.mqttStatusAt = now;
} else if (source === "1b1515f0706978be") {
    // websocket out: "connected N" / "disconnected" / ""
    const m = /(\d+)/.exec(text);
    rt.wsClients = m ? Number(m[1]) : /disconnected/i.test(text) ? 0 : (text === "" ? 0 : null);
    rt.wsStatusAt = now;
} else if (source === "1a0bc41673495b69") {
    // telegram sender: "connected", "messages sent: N", or the last error text
    rt.telegramStatus = text.replace(/bot\d+:[A-Za-z0-9_-]+/g, "bot<redacted>").slice(0, 120);
    rt.telegramStatusFill = s.fill || null;
    rt.telegramStatusAt = now;
}
global.set("aquasenseRuntime", rt);
return null;

// Telegram de-duplication. A notification is sent only when the state changes:
//   - water_quality changes (GOOD / WARNING / DANGER, any direction)
//   - sensor_status becomes an error, or recovers from an error
//   - the very first classified reading (no delivered notification yet)
// Identical consecutive readings never trigger a message. A cooldown
// (config telegram.cooldownSeconds) absorbs rapid flapping around a threshold;
// a change that is still present after the cooldown is sent then.
//
// The last notified state lives in flow context and is restored from the last
// DELIVERED row of notification_log (MySQL) after a Node-RED restart, so a
// restart neither re-sends the current state nor forgets an undelivered change.
// When every retry fails, "Notification: retry" puts the previous state back
// (marked unsent), so the change is attempted again after the cooldown.
// Output 1 → Prepare Telegram, output 2 → load last state from MySQL.
const d = msg.payload;
const cfg = global.get("aquasense") || {};
const cooldownMs = ((cfg.telegram && cfg.telegram.cooldownSeconds) || 300) * 1000;

if (!flow.get("notifyStateLoaded") && !msg._stateLoadAttempted) {
    msg._stateLoadAttempted = true;
    msg._reading = d;
    msg.topic = "SELECT water_quality, sensor_status, UNIX_TIMESTAMP(created_at) AS created_unix " +
        "FROM notification_log WHERE channel = 'telegram' AND delivery_status = 'SENT' AND event_type <> 'TEST' " +
        "AND event_type NOT LIKE 'HISTORICAL_REPLAY%' " +
        "ORDER BY id DESC LIMIT 1";
    msg.payload = [];
    return [null, msg];
}

function sensorCategory(s) {
    s = String(s || "").toUpperCase();
    if (/ERR|FAIL/.test(s)) return "ERROR";
    if (s === "SUCCESS" || s === "OK" || s === "NORMAL") return "OK";
    return "UNREPORTED"; // e.g. "UNKNOWN" when the firmware does not send a status
}

const prev = flow.get("notifyState") || null;
const cur = { quality: d.water_quality, sensor: sensorCategory(d.sensor_status) };

const events = [];
if (!prev || !prev.quality) {
    events.push("INITIAL_STATE");
} else {
    if (prev.quality !== cur.quality) events.push("QUALITY_CHANGE");
    if (prev.sensor !== "ERROR" && cur.sensor === "ERROR") events.push("SENSOR_ERROR");
    if (prev.sensor === "ERROR" && cur.sensor === "OK") events.push("SENSOR_RECOVERED");
}
if (!events.length) return null;

const now = Date.now();
// A sensor error skips the cooldown, except right after a failed delivery
// (prev.unsent) so a network outage never turns into a burst of attempts.
const urgent = events.indexOf("SENSOR_ERROR") !== -1 && !(prev && prev.unsent);
if (prev && prev.at && now - prev.at < cooldownMs && !urgent) {
    node.status({ fill: "yellow", shape: "ring", text: "cooldown: " + events.join(", ") });
    return null;
}

// Remember before sending so an in-flight message is never duplicated.
const next = { quality: cur.quality, sensor: cur.sensor === "UNREPORTED" && prev ? prev.sensor : cur.sensor, at: now };
flow.set("notifyState", next);

const severity = events.indexOf("SENSOR_ERROR") !== -1 ? "ERROR" : cur.quality;
msg.notification = {
    events: events,
    severity: severity,
    quality: cur.quality,
    previous_quality: prev && prev.quality ? prev.quality : null,
    sensor_status: d.sensor_status || null,
    reading_timestamp: d.timestamp,
    attempt: 1,
    committed_at: now,
    prev_state: prev ? { quality: prev.quality || null, sensor: prev.sensor || null } : null,
};
node.status({ fill: "green", shape: "dot", text: events.join(", ") + " → " + cur.quality });
return [msg, null];

// Restore the last notified state from notification_log, then hand the
// reading back to "Notification: dedup".
const row = Array.isArray(msg.payload) ? msg.payload[0] : null;
if (!flow.get("notifyStateLoaded")) {
    if (row) {
        const s = String(row.sensor_status || "").toUpperCase();
        flow.set("notifyState", {
            quality: row.water_quality,
            sensor: /ERR|FAIL/.test(s) ? "ERROR" : (s === "SUCCESS" || s === "OK" || s === "NORMAL") ? "OK" : "UNREPORTED",
            at: Number(row.created_unix) * 1000,
        });
    }
    flow.set("notifyStateLoaded", true);
}
msg.payload = msg._reading;
delete msg._reading;
return msg;

// notification_log could not be read (MySQL down). Continue with the
// in-memory state only; the reading is passed back to the dedup node once.
if (!msg._reading) return null;
msg.payload = msg._reading;
delete msg._reading;
return msg;

// Record every final Telegram result in notification_log (after
// "Notification: retry"; msg.error is set when the last attempt failed). The
// bot token is never stored: it is stripped from error texts.
// created_at and reading_timestamp are stored as UTC.
const n = msg.notification;
if (!n) return null;
const failed = !!msg.error;
const attempts = n.attempt || 1;
let error = null;
if (failed) {
    const lines = String(msg.error).split(/\r?\n/);
    error = ("[" + attempts + " attempt" + (attempts === 1 ? "" : "s") + "] " + (lines[1] || lines[0] || ""))
        .replace(/bot\d+:[A-Za-z0-9_-]+/g, "bot<redacted>").slice(0, 250);
}
const ts = new Date(n.reading_timestamp);
const pad = function (x) { return String(x).padStart(2, "0"); };
const readingSql = isNaN(ts.getTime()) ? null : ts.getUTCFullYear() + "-" + pad(ts.getUTCMonth() + 1) + "-" + pad(ts.getUTCDate()) +
    " " + pad(ts.getUTCHours()) + ":" + pad(ts.getUTCMinutes()) + ":" + pad(ts.getUTCSeconds());

return {
    topic: "INSERT INTO notification_log (created_at, channel, event_type, severity, water_quality, previous_quality, " +
        "sensor_status, reading_timestamp, title, message, delivery_status, error) " +
        "VALUES (UTC_TIMESTAMP(), 'telegram', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
    payload: [
        n.events.join(","), n.severity, n.quality, n.previous_quality, n.sensor_status ? String(n.sensor_status).slice(0, 20) : null,
        readingSql, String(n.title || "").slice(0, 150), n.message || null, failed ? "FAILED" : "SENT", error,
    ],
};

// ---- shared helpers (prepended to API function nodes by build-flow.mjs) ----
// Timestamps in water_quality.timestamp are stored in MySQL as WITA (UTC+8).
// Therefore, no additional +8 hours is applied when deriving session/time.
// API timestamps are returned with +08:00.

const CFG = global.get("aquasense");

function reply(m, status, body) {
    m.statusCode = status;
    m.headers = Object.assign({}, m.headers, {
        "Content-Type": "application/json; charset=utf-8",
        "Cache-Control": "no-store",
        "X-Content-Type-Options": "nosniff",
    });
    m.payload = body;
    m._responded = true;
    return m;
}

function ok(m, data) {
    return reply(m, 200, {
        success: true,
        data: data
    });
}

function fail(m, status, message, code) {
    return reply(m, status, {
        success: false,
        message: message,
        code: code || null
    });
}

function pad(n) {
    return String(n).padStart(2, "0");
}

// "YYYY-MM-DD" WITA calendar date -> Date of 00:00 WITA.
function witaMidnight(dateStr) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
        return null;
    }

    const d = new Date(
        dateStr + "T00:00:00" + CFG.utcOffset
    );

    if (isNaN(d.getTime())) {
        return null;
    }

    // Reject rolled-over dates such as 2026-02-31.
    const back = new Date(
        d.getTime() +
        CFG.utcOffsetMinutes * 60000
    ).toISOString().slice(0, 10);

    return back === dateStr ? d : null;
}

// Session label is derived directly from the WITA hour
// because water_quality.timestamp is already stored as WITA.
function sessionCaseSql(col) {
    const hour = "HOUR(" + col + ")";

    return "CASE " +
        CFG.sessions.map(function (s) {
            return "WHEN " +
                hour +
                " >= " + s.startHour +
                " AND " +
                hour +
                " < " + s.endHour +
                " THEN '" +
                s.name +
                "'";
        }).join(" ") +
        " ELSE '" +
        CFG.outsideSessionLabel +
        "' END";
}

function readingColumns() {
    return "id, device_id, " +
        "DATE_FORMAT(timestamp, '%Y-%m-%dT%H:%i:%s+08:00') AS timestamp, " +
        "CAST(ph_raw AS DOUBLE) AS ph_raw, " +
        "CAST(ph_filtered AS DOUBLE) AS ph_filtered, " +
        "CAST(tds_raw AS DOUBLE) AS tds_raw, " +
        "CAST(tds_filtered AS DOUBLE) AS tds_filtered, " +
        "CAST(turbidity_raw AS DOUBLE) AS turbidity_raw, " +
        "CAST(turbidity_filtered AS DOUBLE) AS turbidity_filtered, " +
        "sensor_status, water_quality, " +
        "(" + sessionCaseSql("timestamp") + ") AS session";
}

// Query-string filters shared by readings / summary / export.
// from, to: WITA calendar dates (inclusive).
// session, quality, search: optional.
function parseFilters(q) {
    q = q || {};

    const where = [];
    const params = [];
    const applied = {};

    const from = q.from
        ? witaMidnight(String(q.from))
        : null;

    const to = q.to
        ? witaMidnight(String(q.to))
        : null;

    if (q.from && !from) {
        return {
            error: "Tanggal awal tidak valid (format YYYY-MM-DD)."
        };
    }

    if (q.to && !to) {
        return {
            error: "Tanggal akhir tidak valid (format YYYY-MM-DD)."
        };
    }

    if (from && to && from > to) {
        return {
            error: "Tanggal awal tidak boleh setelah tanggal akhir."
        };
    }

    // Database timestamp is already WITA.
    if (from) {
        where.push("timestamp >= ?");

        params.push(
            dateToSqlWita(from)
        );

        applied.from = String(q.from);
    }

    if (to) {
        where.push("timestamp < ?");

        params.push(
            dateToSqlWita(
                new Date(
                    to.getTime() + 86400000
                )
            )
        );

        applied.to = String(q.to);
    }

    if (q.session && q.session !== "all") {
        const names = CFG.sessions
            .map(function (s) {
                return s.name;
            })
            .concat(
                CFG.outsideSessionLabel
            );

        if (names.indexOf(q.session) === -1) {
            return {
                error: "Sesi tidak dikenal."
            };
        }

        where.push(
            "(" +
            sessionCaseSql("timestamp") +
            ") = ?"
        );

        params.push(q.session);
        applied.session = q.session;
    }

    if (q.quality && q.quality !== "all") {
        if (
            ["GOOD", "WARNING", "DANGER"]
                .indexOf(q.quality) === -1
        ) {
            return {
                error: "Kategori kualitas tidak dikenal."
            };
        }

        where.push("water_quality = ?");
        params.push(q.quality);
        applied.quality = q.quality;
    }

    const search =
        typeof q.search === "string"
            ? q.search.trim().slice(0, 50)
            : "";

    if (search) {
        const like =
            "%" +
            search.replace(
                /[\\%_]/g,
                function (c) {
                    return "\\" + c;
                }
            ) +
            "%";

        where.push(
            "(DATE_FORMAT(timestamp, '%Y-%m-%d %H:%i:%s') LIKE ?" +
            " OR sensor_status LIKE ?" +
            " OR water_quality LIKE ?" +
            " OR (" +
            sessionCaseSql("timestamp") +
            ") LIKE ?)"
        );

        params.push(
            like,
            like,
            like,
            like
        );

        applied.search = search;
    }

    return {
        where: where.length
            ? "WHERE " + where.join(" AND ")
            : "",
        params: params,
        applied: applied
    };
}

// Convert Date -> "YYYY-MM-DD HH:MM:SS" using WITA.
function dateToSqlWita(d) {
    const wita = new Date(
        d.getTime() +
        CFG.utcOffsetMinutes * 60000
    );

    return wita.getUTCFullYear() +
        "-" +
        pad(wita.getUTCMonth() + 1) +
        "-" +
        pad(wita.getUTCDate()) +
        " " +
        pad(wita.getUTCHours()) +
        ":" +
        pad(wita.getUTCMinutes()) +
        ":" +
        pad(wita.getUTCSeconds());
}

function intParam(value, fallback, min, max) {
    const n = parseInt(value, 10);

    if (!Number.isFinite(n)) {
        return fallback;
    }

    return Math.min(
        max,
        Math.max(min, n)
    );
}

function numOrNull(v) {
    if (v === null || v === undefined) {
        return null;
    }

    const n = Number(v);

    return Number.isFinite(n)
        ? n
        : null;
}

// Admin audit trail.
// Never pass passwords, hashes, tokens or secrets here.
// Audit timestamps remain UTC.
function auditMsg(userId, action, detail, req) {
    return {
        topic:
            "INSERT INTO admin_audit_log " +
            "(user_id, action, detail, ip, created_at) " +
            "VALUES (?, ?, ?, ?, UTC_TIMESTAMP())",

        payload: [
            userId || null,
            action,
            detail
                ? String(detail).slice(0, 255)
                : null,
            req && req.ip
                ? String(req.ip).slice(0, 64)
                : null
        ],
    };
}

