const SESSION_COOKIE = "aquasense_session";

function sessionCookie(req, value, maxAgeMs) {
    const secure =
        !!(
            req &&
            (
                req.secure ||
                req.headers["x-forwarded-proto"] === "https"
            )
        );

    return {
        value: value,
        httpOnly: true,
        sameSite: "strict",
        secure: secure,
        path: "/",
        maxAge: maxAgeMs
    };
}

function clearSessionCookie(req) {
    return {
        value: null,
        httpOnly: true,
        sameSite: "strict",
        secure: !!(
            req &&
            req.secure
        ),
        path: "/"
    };
}

// "Set AquaSense config" runs on start-up;
// CFG is missing only in the first instant.
function notReady(respondIndex) {
    const out = new Array(
        node.outputCount
    ).fill(null);

    out[respondIndex] =
        fail(
            msg,
            503,
            "Sistem sedang memulai. Coba lagi sebentar.",
            "STARTING"
        );

    return out;
