// ---- end shared helpers ----


// /api/water/latest and /api/water/history used to hang when MySQL was
// unreachable (no response was ever sent). Answer with a clear 503 instead.
if (!msg.res || msg._responded) {
    return null;
}

return fail(
    msg,
    503,
    "Database tidak dapat dijangkau. Data tersimpan akan tampil kembali setelah koneksi pulih.",
    "DATABASE_UNAVAILABLE"
);

// Bounded retry between the Telegram sender and the notification log.
// Both sender outputs are wired here; msg.error is set on the error output.
//   - success                → output 2 (log as SENT)
//   - failure, attempts left → resend after a delay (output 1 → sender)
//   - failure, last attempt  → output 2 (log as FAILED) and hand the change
//                              back to "Notification: dedup" (see there)
// Function-node timers are cleared by Node-RED on redeploy/stop, so a pending
// retry never outlives the flow.
const MAX_ATTEMPTS = 3;
const DELAYS_MS = [15000, 45000]; // before attempt 2 and attempt 3

const n = msg.notification;
if (!n) return null;
const attempt = n.attempt || 1;

if (!msg.error) {
    node.status({ fill: "green", shape: "dot", text: "sent (attempt " + attempt + ")" });
    return [null, msg];
}

const reason = String(msg.error).split(/\r?\n/)[0].replace(/bot\d+:[A-Za-z0-9_-]+/g, "bot<redacted>").slice(0, 120);

if (attempt < MAX_ATTEMPTS) {
    const delay = DELAYS_MS[attempt - 1];
    n.attempt = attempt + 1;
    node.status({ fill: "yellow", shape: "ring", text: "retry " + n.attempt + "/" + MAX_ATTEMPTS + " in " + delay / 1000 + " s: " + reason });
    setTimeout(function () {
        delete msg.error;
        node.send([msg, null]);
    }, delay);
    return null;
}

node.status({ fill: "red", shape: "ring", text: "failed after " + attempt + " attempts: " + reason });
if (!n.test) {
    // Undo the state committed by the dedup node, unless a newer notification
    // has been committed since — then that one owns the state.
    const state = flow.get("notifyState");
    if (state && state.at === n.committed_at) {
        const restored = n.prev_state || { quality: null, sensor: null };
        flow.set("notifyState", { quality: restored.quality, sensor: restored.sensor, at: Date.now(), unsent: true });
    }
}
return [null, msg];

// Historical replay (inject "Replay: preview" / "Replay: send next 5").
// Re-sends water-quality events computed from the readings ALREADY stored in
// water_quality — nothing is inserted into or changed in that table. Each
// sent message is logged in notification_log as HISTORICAL_REPLAY with the
// original measurement time in reading_timestamp; created_at is the real send
// time. Step 1: load the events already delivered by a previous replay.
const mode = msg.payload === "send" ? "send" : "preview";
const state = global.get("aquasenseReplay") || {};
if (mode === "send" && state.busy_until && Date.now() < state.busy_until) {
    node.status({ fill: "yellow", shape: "ring", text: "batch still running — try again later" });
    global.set("aquasenseReplay", Object.assign({}, state, { last_refused_at: new Date().toISOString() }));
    return null;
}
msg.replayMode = mode;
msg.topic = "SELECT DATE_FORMAT(reading_timestamp, '%Y-%m-%dT%H:%i:%sZ') AS ts FROM notification_log " +
    "WHERE channel = 'telegram' AND event_type LIKE 'HISTORICAL_REPLAY%' AND delivery_status = 'SENT'";
msg.payload = [];
return msg;

// Historical replay, step 2: remember what was already delivered, then read
// every stored reading in measurement order (timestamp holds WITA → +08:00).
msg.replaySent = (Array.isArray(msg.payload) ? msg.payload : [])
    .map(function (r) { return new Date(r.ts).getTime(); })
    .filter(function (t) { return !isNaN(t); });
msg.topic = "SELECT id, device_id, DATE_FORMAT(timestamp, '%Y-%m-%dT%H:%i:%s+08:00') AS timestamp, " +
    "ph_filtered, tds_filtered, turbidity_filtered, sensor_status, water_quality " +
    "FROM water_quality ORDER BY timestamp ASC, id ASC";
msg.payload = [];
return msg;

// Historical replay, step 3: derive the events with the SAME rule as
// "Notification: dedup" (only on a water_quality change, minimum gap =
// telegram cooldown) over the stored readings, skip those already delivered,
// and — in "send" mode only — send the next batch (oldest first) through the
// Telegram sender → retry → notification_log path.
// The result (full event list with sent flags) is kept in global
// "aquasenseReplay" and shown in the node status.
const BATCH = 5;
const SPACING_MS = 3000;
const LOCK_MS = 90000; // batch spacing + the retry window (15 s + 45 s) + margin
const cfg = global.get("aquasense") || {};
const cooldownMs = ((cfg.telegram && cfg.telegram.cooldownSeconds) || 300) * 1000;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const sent = new Set(msg.replaySent || []);

const events = [];
let state = null;
let last = null;
for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    const q = r.water_quality;
    if (["GOOD", "WARNING", "DANGER"].indexOf(q) === -1 || q === state) continue;
    const t = new Date(r.timestamp).getTime();
    if (last !== null && t - last < cooldownMs) continue;
    events.push({ row: r, previous: state, at: t });
    state = q;
    last = t;
}

function wita(date) {
    return new Date(date).toLocaleString("id-ID", {
        timeZone: "Asia/Makassar",
        day: "2-digit", month: "short", year: "numeric",
        hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false,
    }) + " WITA";
}

// Same format as "Prepare Telegram"; every value comes from the stored row and
// the time is the original measurement time.
function build(e) {
    const d = e.row;
    let statusIcon, statusTitle, action;
    if (d.water_quality === "GOOD") {
        statusIcon = "🟢";
        statusTitle = "GOOD — KUALITAS AIR BAIK";
        action = "✅ Kondisi air memenuhi batas parameter pemantauan yang digunakan oleh sistem.";
    } else if (d.water_quality === "WARNING") {
        statusIcon = "🟡";
        statusTitle = "WARNING — PERHATIAN";
        action = "⚠️ Disarankan melakukan pemeriksaan lebih lanjut terhadap parameter yang terdeteksi.";
    } else {
        statusIcon = "🔴";
        statusTitle = "DANGER — BAHAYA";
        action = "⛔ Lakukan pemeriksaan lebih lanjut sebelum menentukan penggunaan air.";
    }
    const reason = e.previous ? "🔄 Perubahan status: " + e.previous + " → " + d.water_quality : "ℹ️ Status awal pemantauan";
    const content =
`💧 AQUASENSE BORIKAMASE

${statusIcon} ${statusTitle}
${reason}

📊 Hasil Pemantauan (Kalman Filter)
• pH: ${Number(d.ph_filtered)}
• TDS: ${Number(d.tds_filtered)} ppm
• Kekeruhan: ${Number(d.turbidity_filtered)} NTU

${action}

📍 Lokasi: Sumur Borikamase
🕐 Waktu: ${wita(e.at)}`;
    return { title: statusIcon + " " + statusTitle, content: content };
}

const summary = function (e) {
    return { reading_id: e.row.id, measured_at: e.row.timestamp, previous: e.previous, quality: e.row.water_quality, sent: sent.has(e.at) };
};
const pending = events.filter(function (e) { return !sent.has(e.at); });
const mode = msg.replayMode;
const batch = mode === "send" ? pending.slice(0, BATCH) : [];

batch.forEach(function (e, i) {
    const m = build(e);
    setTimeout(function () {
        node.send({
            payload: { chatId: "YOUR_TELEGRAM_CHAT_ID", type: "message", content: m.content },
            notification: {
                historical: true,
                events: ["HISTORICAL_REPLAY", e.previous ? "QUALITY_CHANGE" : "INITIAL_STATE"],
                severity: e.row.water_quality,
                quality: e.row.water_quality,
                previous_quality: e.previous,
                sensor_status: e.row.sensor_status || null,
                reading_timestamp: e.row.timestamp,
                attempt: 1,
                title: m.title,
                message: m.content,
            },
        });
    }, i * SPACING_MS);
});

const now = Date.now();
global.set("aquasenseReplay", {
    mode: mode,
    ran_at: new Date(now).toISOString(),
    busy_until: batch.length ? now + LOCK_MS : null,
    rows_scanned: rows.length,
    first_reading: rows.length ? rows[0].timestamp : null,
    last_reading: rows.length ? rows[rows.length - 1].timestamp : null,
    cooldown_seconds: cooldownMs / 1000,
    total_events: events.length,
    already_sent: events.length - pending.length,
    remaining_after_batch: pending.length - batch.length,
    batch: batch.map(summary),
    events: events.map(summary),
    preview_messages: mode === "preview" ? pending.slice(0, BATCH).map(function (e) { return build(e).content; }) : [],
});
node.status({
    fill: batch.length ? "green" : "grey", shape: "dot",
    text: mode + ": " + events.length + " events, " + (events.length - pending.length) + " sent, " +
        (batch.length ? "sending " + batch.length : pending.length + " remaining"),
});
return null;

// Historical replay: a MySQL query failed — nothing was sent.
const state = global.get("aquasenseReplay") || {};
const text = String((msg.error && msg.error.message) || msg.error || "query failed").slice(0, 200);
global.set("aquasenseReplay", Object.assign({}, state, { error: text, error_at: new Date().toISOString() }));
node.status({ fill: "red", shape: "ring", text: text });
return null;

// ==========================================
// CALCULATE LATENCY - AQUASENSE BORIKAMASE
// Cabang PENGUJIAN, terpisah dari jalur utama.
// Perhitungan menggunakan Unix Epoch milidetik.
// Tampilan waktu menggunakan WITA (UTC+8).
// ==========================================

// Waktu penerimaan pesan oleh Function Node
const receivedAt = Date.now();
const p = msg.payload;

// Batas validasi timestamp
const MIN_VALID_TS = 1704067200000;
const MAX_CLOCK_DIFFERENCE = 1000;

// Offset WITA
const WITA_OFFSET = 8 * 60 * 60 * 1000;

// ==========================================
// FORMAT WAKTU WITA
// ==========================================
function formatWITA(timestamp) {
    return new Date(timestamp + WITA_OFFSET)
        .toISOString()
        .replace("T", " ")
        .replace(/\.\d{3}Z$/, " WITA");
}

// ==========================================
// FUNGSI PENOLAKAN
// ==========================================
function reject(statusText, warning) {
    node.warn("LATENCY ERROR | " + warning);

    node.status({
        fill: "yellow",
        shape: "ring",
        text: statusText
    });

    return null;
}

// ==========================================
// 1. DIAGNOSTIK WAKTU NODE-RED
// ==========================================
node.warn("========== TIME DIAGNOSTIC ==========");
node.warn("Node-RED Epoch: " + receivedAt);
node.warn("Node-RED ISO: " + new Date(receivedAt).toISOString());
node.warn("Node-RED WITA: " + formatWITA(receivedAt));
node.warn("=====================================");

// ==========================================
// 2. VALIDASI PAYLOAD
// ==========================================
if (
    !p ||
    typeof p !== "object" ||
    Array.isArray(p)
) {
    return reject(
        "Payload tidak valid",
        "Payload bukan object JSON."
    );
}

// ==========================================
// 3. PERIKSA TIMESTAMP ESP32
// ==========================================
if (
    p.timestamp_sent === undefined ||
    p.timestamp_sent === null ||
    p.timestamp_sent === ""
) {
    return reject(
        "Timestamp tidak tersedia",
        "timestamp_sent tidak ditemukan. Periksa firmware ESP32."
    );
}

// ==========================================
// 4. KONVERSI TIMESTAMP
// ==========================================
const sentAt = Number(p.timestamp_sent);

// ==========================================
// 5. VALIDASI FORMAT TIMESTAMP
// ==========================================
if (
    !Number.isFinite(sentAt) ||
    !Number.isInteger(sentAt) ||
    sentAt < MIN_VALID_TS
) {
    return reject(
        "Timestamp tidak valid",
        "Nilai timestamp_sent bukan Unix epoch milidetik: " +
        p.timestamp_sent
    );
}

// ==========================================
// 6. PEMERIKSAAN SELISIH JAM
// ==========================================
const clockDifference = receivedAt - sentAt;
const absoluteDifference = Math.abs(clockDifference);

if (absoluteDifference > MAX_CLOCK_DIFFERENCE) {

    const direction = clockDifference < 0
        ? "ESP32 lebih maju"
        : "Node-RED lebih maju";

    node.warn(
        "CLOCK MISMATCH | " +
        "Waktu ESP32: " + formatWITA(sentAt) + " | " +
        "Waktu Node-RED: " + formatWITA(receivedAt) + " | " +
        direction + " | " +
        "Selisih: " + absoluteDifference + " ms"
    );

    node.status({
        fill: "red",
        shape: "ring",
        text: "Clock mismatch: " +
            absoluteDifference + " ms"
    });

    return null;
}

// ==========================================
// 7. HITUNG LATENSI
// ==========================================
const latency = receivedAt - sentAt;

// ==========================================
// 8. VALIDASI LATENSI
// ==========================================
if (
    !Number.isFinite(latency) ||
    latency < 0
) {
    return reject(
        "Latency tidak valid",
        "Nilai latensi negatif atau tidak valid."
    );
}

// ==========================================
// 9. STATISTIK BERJALAN
// ==========================================
let stats = context.get("stats") || {
    count: 0,
    sum: 0,
    min: null,
    max: null
};

stats.count++;
stats.sum += latency;

stats.min = stats.min === null
    ? latency
    : Math.min(stats.min, latency);

stats.max = stats.max === null
    ? latency
    : Math.max(stats.max, latency);

context.set("stats", stats);

// ==========================================
// 10. HITUNG RATA-RATA
// ==========================================
const average = stats.sum / stats.count;

// ==========================================
// 11. STATUS FUNCTION NODE
// ==========================================
node.status({
    fill: "green",
    shape: "dot",
    text:
        latency.toFixed(2) +
        " ms | Avg: " +
        average.toFixed(2) +
        " ms | n=" +
        stats.count
});

// ==========================================
// 12. OUTPUT PENGUJIAN
// ==========================================
return {
    topic: msg.topic,

    payload: {
        latency_ms: Number(latency.toFixed(2)),

        timestamp_sent: sentAt,
        timestamp_received: receivedAt,

        waktu_pengiriman: formatWITA(sentAt),
        waktu_penerimaan: formatWITA(receivedAt),

        clock_difference_ms: Number(
            absoluteDifference.toFixed(2)
        ),

        count: stats.count,
        avg_ms: Number(average.toFixed(2)),
        min_ms: Number(stats.min.toFixed(2)),
        max_ms: Number(stats.max.toFixed(2))
    }
};

