            { parameter: "tds", unit: "ppm", good: "< 300", warning: "300 – < 600", danger: "≥ 600", goodBelow: 300, warningBelow: 600 },
            { parameter: "turbidity", unit: "NTU", good: "< 5", warning: "5 – < 50", danger: "≥ 50", goodBelow: 5, warningBelow: 50 },
        ],
