const rt = global.get("aquasenseRuntime") || {};
// Pipeline counters are "since startedAt".
rt.startedAt = new Date().toISOString();
rt.messagesReceived = 0;
rt.validReadings = 0;
global.set("aquasenseRuntime", rt);
node.status({ fill: "green", shape: "dot", text: "config loaded" });
