if (!state) {
    if (global.get("aquasenseSchemaReady") || flow.get("setupRunning")) return null;
    flow.set("setupRunning", true);
    state = { i: -1, results: {} };
} else {
    const done = STEPS[state.i];
    if (done && done.id) state.results[done.id] = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;
}

let next = state.i + 1;
while (next < STEPS.length && STEPS[next].onlyIf && !STEPS[next].onlyIf(state.results)) next++;

if (next >= STEPS.length) {
    flow.set("setupRunning", false);
    global.set("aquasenseSchemaReady", true);
    node.status({ fill: "green", shape: "dot", text: "schema ready" });
    node.log("AquaSense schema check complete");
    return null;
}

state.i = next;
node.status({ fill: "blue", shape: "ring", text: "step " + (next + 1) + "/" + STEPS.length });
return { topic: STEPS[next].sql, payload: STEPS[next].params || [], _setup: state };

// A setup statement failed (usually MySQL not reachable yet). The periodic
// "retry setup" inject starts again from the first (idempotent) step.
flow.set("setupRunning", false);
const text = String((msg.error && msg.error.message) || "unknown error");
node.status({ fill: "red", shape: "ring", text: "setup waiting: " + text.slice(0, 40) });
