// ---- password hashing helpers (prepended; requires the "crypto" module in Setup) ----

// Format:
// scrypt$N$r$p$<salt base64>$<key base64>

const SCRYPT = {
    N: 16384,
    r: 8,
    p: 1,
    keylen: 64,
    maxmem: 64 * 1024 * 1024
};

// Used when the username does not exist so the response time
// does not reveal it.
const DUMMY_HASH =
    "scrypt$16384$8$1$AAAAAAAAAAAAAAAAAAAAAA==$"
    + Buffer.alloc(64).toString("base64");

function hashPassword(password, cb) {
    const salt = crypto.randomBytes(16);

    crypto.scrypt(
        password,
        salt,
        SCRYPT.keylen,
        {
            N: SCRYPT.N,
            r: SCRYPT.r,
            p: SCRYPT.p,
            maxmem: SCRYPT.maxmem
        },
        function (err, key) {
            if (err) {
                return cb(err);
            }

            cb(
                null,
                [
                    "scrypt",
                    SCRYPT.N,
                    SCRYPT.r,
                    SCRYPT.p,
                    salt.toString("base64"),
                    key.toString("base64")
                ].join("$")
            );
        }
    );
}

function verifyPassword(password, stored, cb) {
    const parts =
        String(stored || "").split("$");

    if (
        parts.length !== 6 ||
        parts[0] !== "scrypt"
    ) {
        return cb(false);
    }

    const N = Number(parts[1]);
    const r = Number(parts[2]);
    const p = Number(parts[3]);

    const salt =
        Buffer.from(parts[4], "base64");

    const expected =
        Buffer.from(parts[5], "base64");

    crypto.scrypt(
        String(password),
        salt,
        expected.length,
        {
            N: N,
            r: r,
            p: p,
            maxmem: SCRYPT.maxmem
        },
        function (err, key) {
            cb(
                !err &&
                key.length === expected.length &&
                crypto.timingSafeEqual(
                    key,
                    expected
                )
            );
        }
    );
}

function sha256(value) {
    return crypto
        .createHash("sha256")
        .update(String(value))
        .digest("hex");
}

