// ============================================================
// WITA DATE VALIDATION
//
// Input:
// YYYY-MM-DD
//
// Contoh:
// 2026-09-29
//
// Dipastikan valid sebagai tanggal WITA.
// ============================================================

function witaMidnight(dateStr) {

    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
        return null;
    }

    const d = new Date(
        dateStr + "T00:00:00+08:00"
    );

    if (isNaN(d.getTime())) {
        return null;
    }


    // Pastikan tanggal tidak rollover
    // misalnya 2026-02-31.

    const parts =
        new Intl.DateTimeFormat(
            "en-CA",
            {
                timeZone: "Asia/Makassar",
                year: "numeric",
                month: "2-digit",
                day: "2-digit"
            }
        ).formatToParts(d);


    const year =
        parts.find(
            function (x) {
                return x.type === "year";
            }
        ).value;


    const month =
        parts.find(
            function (x) {
                return x.type === "month";
            }
        ).value;


    const day =
        parts.find(
            function (x) {
                return x.type === "day";
            }
        ).value;


    const back =
        year +
        "-" +
        month +
        "-" +
        day;


    return back === dateStr
        ? d
        : null;
}


