// ============================================================
// QUERY-STRING FILTERS
// ============================================================

// from, to:
// WITA calendar dates (inclusive)
//
// session:
// optional
//
// quality:
// optional
//
// search:
// optional
//
function parseFilters(q) {

    q = q || {};

    const where = [];
    const params = [];
    const applied = {};

    const fromStr =
        q.from
            ? String(q.from)
            : null;

    const toStr =
        q.to
            ? String(q.to)
            : null;


    // ========================================================
    // VALIDATE FROM
    // ========================================================

    const from =
        fromStr
            ? witaMidnight(fromStr)
            : null;

    if (
        fromStr &&
        !from
    ) {

        return {
            error:
                "Tanggal awal tidak valid (format YYYY-MM-DD)."
        };
    }


    // ========================================================
    // VALIDATE TO
    // ========================================================

    const to =
        toStr
            ? witaMidnight(toStr)
            : null;

    if (
        toStr &&
        !to
    ) {

        return {
            error:
                "Tanggal akhir tidak valid (format YYYY-MM-DD)."
        };
    }


    // ========================================================
    // CHECK DATE ORDER
    // ========================================================

    if (
        fromStr &&
        toStr &&
        fromStr > toStr
    ) {

        return {
            error:
                "Tanggal awal tidak boleh setelah tanggal akhir."
        };
    }


    // ========================================================
    // FROM
    // ========================================================

    if (fromStr) {

        where.push(
            "timestamp >= ?"
        );

        params.push(
            fromStr +
            " 00:00:00"
        );

        applied.from =
            fromStr;
    }


    // ========================================================
    // TO
    //
    // Inclusive.
    //
    // Kalau to = 2026-09-29,
    // query sampai sebelum:
    //
    // 2026-09-30 00:00:00
    //
    // ========================================================

    if (toStr) {

        const nextDay =
            new Date(
                toStr +
                "T00:00:00+08:00"
            );

