function parseFilters(q) {

    q = q || {};

    const where = [];
    const params = [];
    const applied = {};

    const fromStr =
        q.from
            ? String(q.from)
            : null;

    const toStr =
        q.to
            ? String(q.to)
            : null;


    // ========================================================
    // VALIDATE FROM
    // ========================================================

    const from =
        fromStr
            ? witaMidnight(fromStr)
            : null;

    if (
        fromStr &&
        !from
    ) {

        return {
            error:
                "Tanggal awal tidak valid (format YYYY-MM-DD)."
        };
    }


    // ========================================================
    // VALIDATE TO
    // ========================================================

    const to =
        toStr
            ? witaMidnight(toStr)
            : null;

    if (
        toStr &&
        !to
    ) {

        return {
            error:
                "Tanggal akhir tidak valid (format YYYY-MM-DD)."
        };
    }


    // ========================================================
    // CHECK DATE ORDER
    // ========================================================

    if (
        fromStr &&
        toStr &&
        fromStr > toStr
    ) {

        return {
