    // 2026-09-29 00:00:00
    // ========================================================

    if (fromStr) {

        where.push(
            "timestamp >= ?"
        );

        params.push(
            fromStr +
            " 00:00:00"
        );

        applied.from =
            fromStr;
    }


    // ========================================================
    // TO DATE
    //
    // Inclusive sampai akhir tanggal.
    //
    // Kalau to = 2026-09-29:
    //
    // timestamp < 2026-09-30 00:00:00
    // ========================================================

    if (toStr) {

        const nextDay =
            new Date(
                toStr +
                "T00:00:00+08:00"
            );

