                }
            ).formatToParts(nextDay);


        const year =
            parts.find(function (x) {
                return x.type === "year";
            }).value;

        const month =
            parts.find(function (x) {
                return x.type === "month";
            }).value;

        const day =
            parts.find(function (x) {
                return x.type === "day";
            }).value;


        where.push(
            "timestamp < ?"
        );

        params.push(
            year +
            "-" +
            month +
            "-" +
            day +
            " 00:00:00"
        );

        applied.to =
            toStr;
    }


    // ========================================================
    // SESSION FILTER
    // ========================================================

    if (
        q.session &&
        q.session !== "all"
    ) {

        const names =
            CFG.sessions
                .map(function (s) {
                    return s.name;
                })
                .concat(
                    CFG.outsideSessionLabel
                );


        if (
            names.indexOf(
                q.session
            ) === -1
        ) {

            return {
                error:
                    "Sesi tidak dikenal."
            };
        }


        where.push(
            "(" +
            sessionCaseSql("timestamp") +
            ") = ?"
        );

        params.push(
            q.session
        );

        applied.session =
            q.session;
    }


    // ========================================================
    // QUALITY FILTER
    // ========================================================

    if (
        q.quality &&
        q.quality !== "all"
    ) {

        if (
            [
                "GOOD",
                "WARNING",
                "DANGER"
            ].indexOf(
                q.quality
            ) === -1
        ) {

            return {
                error:
                    "Kategori kualitas tidak dikenal."
            };
        }


        where.push(
            "water_quality = ?"
        );

        params.push(
            q.quality
        );

        applied.quality =
            q.quality;
    }


    // ========================================================
    // SEARCH
    // ========================================================

    const search =
        typeof q.search === "string"
            ? q.search
                .trim()
                .slice(0, 50)
            : "";


    if (search) {

        const like =
            "%" +
            search.replace(
                /[\\%_]/g,
                function (c) {
                    return "\\" + c;
                }
            ) +
            "%";


        where.push(
            "(" +

            "DATE_FORMAT(" +
            "timestamp, " +
            "'%Y-%m-%d %H:%i:%s'" +
            ") LIKE ?" +

            " OR sensor_status LIKE ?" +

            " OR water_quality LIKE ?" +

            " OR (" +
            sessionCaseSql(
                "timestamp"
            ) +
            ") LIKE ?" +

            ")"
        );


        params.push(
            like,
            like,
            like,
            like
        );

        applied.search =
            search;
    }


    return {
        where:
            where.length
                ? "WHERE " +
                where.join(" AND ")
                : "",

        params:
            params,

        applied:
            applied
    };
}


