        ")";

    return (
        "CASE " +

        CFG.sessions
            .map(function (s) {

                return (
                    "WHEN " +
                    hour +
                    " >= " +
                    s.startHour +

                    " AND " +
                    hour +
                    " < " +
                    s.endHour +

                    " THEN '" +
                    s.name +
                    "'"
                );

            })
            .join(" ") +

        " ELSE '" +
        CFG.outsideSessionLabel +
        "' END"
    );
}


