// ============================================================
// FIELDS
//
// Statistik:
// AVG
// MIN
// MAX
// COUNT
//
// Untuk raw dan filtered.
// ============================================================

const FIELDS = [

    "ph_raw",
    "ph_filtered",

    "tds_raw",
    "tds_filtered",

    "turbidity_raw",
    "turbidity_filtered"

];


const stats =
    FIELDS
        .map(function (c) {

            return (

                "CAST(AVG(" +
                c +
                ") AS DOUBLE) AS " +
                c +
                "_avg, " +

                "CAST(MIN(" +
                c +
                ") AS DOUBLE) AS " +
                c +
                "_min, " +

                "CAST(MAX(" +
                c +
                ") AS DOUBLE) AS " +
                c +
                "_max, " +

                "COUNT(" +
                c +
                ") AS " +
                c +
                "_n"

            );

        })
        .join(", ");


// ============================================================
// SAVE FILTERS
// ============================================================

msg._filters =
    f;


// ============================================================
// SUMMARY QUERY
// ============================================================

msg.topic =

    "SELECT " +

    // Total rows
    "COUNT(*) AS total_rows, " +

    // GOOD
    "CAST(" +
    "COALESCE(" +
    "SUM(water_quality = 'GOOD'), " +
    "0" +
    ")" +
    " AS UNSIGNED) AS good, " +

    // WARNING
    "CAST(" +
    "COALESCE(" +
    "SUM(water_quality = 'WARNING'), " +
    "0" +
    ")" +
    " AS UNSIGNED) AS warning, " +

    // DANGER
    "CAST(" +
    "COALESCE(" +
    "SUM(water_quality = 'DANGER'), " +
    "0" +
    ")" +
    " AS UNSIGNED) AS danger, " +

    // Sensor statistics
    stats +
    ", " +

    // First timestamp
    "DATE_FORMAT(" +
    "MIN(timestamp), " +
    "'%Y-%m-%dT%H:%i:%s+08:00'" +
    ") AS first_at, " +

    // Last timestamp
    "DATE_FORMAT(" +
    "MAX(timestamp), " +
    "'%Y-%m-%dT%H:%i:%s+08:00'" +
    ") AS last_at " +

    // Table
    "FROM water_quality " +

    // Filter
    f.where;


// ============================================================
// MYSQL PARAMETERS
// ============================================================

msg.payload =
    f.params.slice();


// ============================================================
// OUTPUT 1 → MYSQL
// OUTPUT 2 → ERROR
// ============================================================

return [
    msg,
    null
];

// ---- shared helpers (prepended to API function nodes by build-flow.mjs) ----
// Timestamp pada water_quality disimpan di MySQL sebagai WITA (UTC+8) DATETIME.
// API mengirim timestamp water_quality dengan offset +08:00.
//
// Contoh:
// MySQL : 2026-09-29 10:32:39
// API   : 2026-09-29T10:32:39+08:00

const CFG = global.get("aquasense");

function reply(m, status, body) {
    m.statusCode = status;
    m.headers = Object.assign({}, m.headers, {
        "Content-Type": "application/json; charset=utf-8",
        "Cache-Control": "no-store",
        "X-Content-Type-Options": "nosniff",
    });
    m.payload = body;
    m._responded = true;
    return m;
}

function ok(m, data) {
    return reply(m, 200, {
        success: true,
        data: data
    });
}

function fail(m, status, message, code) {
    return reply(m, status, {
        success: false,
        message: message,
        code: code || null
    });
}

function pad(n) {
    return String(n).padStart(2, "0");
}


// ============================================================
// WITA DATE VALIDATION
// ============================================================

function witaMidnight(dateStr) {

    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
        return null;
    }

    const d = new Date(
        dateStr + "T00:00:00+08:00"
    );

    if (isNaN(d.getTime())) {
        return null;
    }

    // Reject rolled-over dates seperti 2026-02-31
    const parts = new Intl.DateTimeFormat(
        "en-CA",
        {
            timeZone: "Asia/Makassar",
            year: "numeric",
            month: "2-digit",
            day: "2-digit"
        }
    ).formatToParts(d);

    const year = parts.find(function (x) {
        return x.type === "year";
    }).value;

    const month = parts.find(function (x) {
        return x.type === "month";
    }).value;

    const day = parts.find(function (x) {
        return x.type === "day";
    }).value;

    const back =
        year + "-" +
        month + "-" +
        day;

    return back === dateStr ? d : null;
}


// ============================================================
// SESSION
//
// water_quality.timestamp sudah WITA.
// Jadi langsung gunakan HOUR(timestamp).
// ============================================================

function sessionCaseSql(col) {

    const hour =
        "HOUR(" + col + ")";

    return "CASE " +
        CFG.sessions.map(function (s) {

            return (
                "WHEN " +
                hour +
                " >= " +
                s.startHour +
                " AND " +
                hour +
                " < " +
                s.endHour +
                " THEN '" +
                s.name +
                "'"
            );

        }).join(" ") +

        " ELSE '" +
        CFG.outsideSessionLabel +
        "' END";
}


