// ============================================================
// QUERY FILTERS
// ============================================================

function parseFilters(q) {

    q = q || {};

    const where = [];
    const params = [];
    const applied = {};

    const fromStr =
        q.from
            ? String(q.from)
            : null;

    const toStr =
        q.to
            ? String(q.to)
            : null;


    // ========================================================
    // VALIDATE FROM
    // ========================================================

    const from =
        fromStr
            ? witaMidnight(fromStr)
            : null;

    if (
        fromStr &&
        !from
    ) {
        return {
            error:
                "Tanggal awal tidak valid (format YYYY-MM-DD)."
        };
    }


    // ========================================================
    // VALIDATE TO
    // ========================================================

    const to =
        toStr
            ? witaMidnight(toStr)
            : null;

    if (
        toStr &&
        !to
    ) {
        return {
            error:
                "Tanggal akhir tidak valid (format YYYY-MM-DD)."
        };
    }


    // ========================================================
    // CHECK DATE ORDER
    // ========================================================

    if (
        fromStr &&
        toStr &&
        fromStr > toStr
    ) {
        return {
            error:
                "Tanggal awal tidak boleh setelah tanggal akhir."
        };
    }


    // ========================================================
    // FROM DATE
    // ========================================================

    if (fromStr) {

        where.push(
            "timestamp >= ?"
        );

        params.push(
            fromStr +
            " 00:00:00"
        );

        applied.from =
            fromStr;
    }


    // ========================================================
    // TO DATE
    //
    // Inclusive sampai akhir tanggal.
    // ========================================================

    if (toStr) {

        const nextDay =
            new Date(
                toStr +
                "T00:00:00+08:00"
            );

        nextDay.setUTCDate(
            nextDay.getUTCDate() + 1
        );

        const parts =
            new Intl.DateTimeFormat(
                "en-CA",
                {
                    timeZone: "Asia/Makassar",
                    year: "numeric",
                    month: "2-digit",
                    day: "2-digit"
                }
            ).formatToParts(nextDay);

        const year =
            parts.find(function (x) {
                return x.type === "year";
            }).value;

        const month =
            parts.find(function (x) {
                return x.type === "month";
            }).value;

        const day =
            parts.find(function (x) {
                return x.type === "day";
            }).value;

        where.push(
            "timestamp < ?"
        );

        params.push(
            year +
            "-" +
            month +
            "-" +
            day +
            " 00:00:00"
        );

        applied.to =
            toStr;
    }


    // ========================================================
    // SESSION FILTER
    // ========================================================

    if (
        q.session &&
        q.session !== "all"
    ) {

        const names =
            CFG.sessions
                .map(function (s) {
                    return s.name;
                })
                .concat(
                    CFG.outsideSessionLabel
                );

        if (
            names.indexOf(
                q.session
            ) === -1
        ) {
            return {
                error:
                    "Sesi tidak dikenal."
            };
        }

        where.push(
            "(" +
            sessionCaseSql("timestamp") +
            ") = ?"
        );

        params.push(
            q.session
        );

        applied.session =
            q.session;
    }


    // ========================================================
    // QUALITY FILTER
    // ========================================================

    if (
        q.quality &&
        q.quality !== "all"
    ) {

        if (
            [
                "GOOD",
                "WARNING",
                "DANGER"
            ].indexOf(
                q.quality
            ) === -1
        ) {
            return {
                error:
                    "Kategori kualitas tidak dikenal."
            };
        }

        where.push(
            "water_quality = ?"
        );

        params.push(
            q.quality
        );

        applied.quality =
            q.quality;
    }


    // ========================================================
    // SEARCH
    // ========================================================

    const search =
        typeof q.search === "string"
            ? q.search
                .trim()
                .slice(0, 50)
            : "";

    if (search) {

        const like =
            "%" +
            search.replace(
                /[\\%_]/g,
                function (c) {
                    return "\\" + c;
                }
            ) +
            "%";

        where.push(
            "(" +

            "DATE_FORMAT(" +
            "timestamp, " +
            "'%Y-%m-%d %H:%i:%s'" +
            ") LIKE ?" +

            " OR sensor_status LIKE ?" +

            " OR water_quality LIKE ?" +

            " OR (" +
            sessionCaseSql(
                "timestamp"
            ) +
            ") LIKE ?" +

            ")"
        );

        params.push(
            like,
            like,
            like,
            like
        );

        applied.search =
            search;
    }


    return {
        where:
            where.length
                ? "WHERE " +
                where.join(" AND ")
                : "",

        params:
            params,

        applied:
            applied
    };
}


