// ============================================================
// SUMMARY RESULT
// ============================================================

// Total readings = GOOD + WARNING + DANGER.
// Rows dengan kategori lain dilaporkan sebagai unclassified.
// Tidak dihitung sebagai GOOD.

const r =
    (
        Array.isArray(msg.payload) &&
        msg.payload[0]
    ) || {};

const good =
    Number(r.good) || 0;

const warning =
    Number(r.warning) || 0;

const danger =
    Number(r.danger) || 0;

const totalRows =
    Number(r.total_rows) || 0;


// ============================================================
// SENSOR STATISTICS
// ============================================================

const stats = {};

[
    "ph",
    "tds",
    "turbidity"
].forEach(function (p) {

    stats[p] = {};

    [
        "raw",
        "filtered"
    ].forEach(function (kind) {

        const c =
            p +
            "_" +
            kind;

        stats[p][kind] = {

            avg:
                numOrNull(
                    r[c + "_avg"]
                ),

            min:
                numOrNull(
                    r[c + "_min"]
                ),

            max:
                numOrNull(
                    r[c + "_max"]
                ),

            n:
                Number(
                    r[c + "_n"]
                ) || 0
        };
    });
});


// ============================================================
// RESPONSE
// ============================================================

return ok(msg, {

    total:
        good +
        warning +
        danger,

    good:
        good,

    warning:
        warning,

    danger:
        danger,

    unclassified:
        totalRows -
        (
            good +
            warning +
            danger
        ),

    stats:
        stats,

    first_at:
        r.first_at ||
        null,

    last_at:
        r.last_at ||
        null,

    filters:
        msg._filters.applied,
});

