// POST /api/auth/login — validate input and apply the per-IP lockout.
// Output 1 → user lookup, output 2 → response.

if (!CFG) return notReady(1);

const body =
    msg.payload &&
        typeof msg.payload === "object"
        ? msg.payload
        : {};

const username =
    typeof body.username === "string"
        ? body.username.trim()
        : "";

const password =
    typeof body.password === "string"
        ? body.password
        : "";

if (
    !username ||
    !password ||
    username.length > 64 ||
    password.length > 128
) {
    return [
        null,
        fail(
            msg,
            400,
            "Username dan password wajib diisi.",
            "INVALID_INPUT"
        )
    ];
}

const now = Date.now();

const attempts =
    flow.get("loginAttempts") || {};

for (const key of Object.keys(attempts)) {
    const a = attempts[key];

    if (
        (a.lockedUntil || 0) < now &&
        now - a.first >
        CFG.auth.lockoutMinutes * 60000
    ) {
        delete attempts[key];
    }
}

flow.set("loginAttempts", attempts);

const ip =
    String(
        msg.req.ip || "unknown"
    );

const rec = attempts[ip];

if (
    rec &&
    rec.lockedUntil &&
    rec.lockedUntil > now
) {
    const minutes =
        Math.ceil(
            (rec.lockedUntil - now) / 60000
        );

    return [
        null,
        fail(
            msg,
            429,
            "Terlalu banyak percobaan login. Coba lagi dalam " +
            minutes +
            " menit.",
            "LOCKED"
        )
    ];
}

msg._login = {
    username: username,
    password: password,
    ip: ip
};

msg.topic =
    "SELECT " +
    USER_COLUMNS +
    ", u.password_hash " +
    "FROM users u " +
    "WHERE u.username = ? " +
    "LIMIT 1";

msg.payload = [username];

return [msg, null];

