// ---- password hashing helpers ----
// requires the "crypto" module in Setup

// Format:
// scrypt$N$r$p$<salt base64>$<key base64>

const SCRYPT = {
    N: 16384,
    r: 8,
    p: 1,
    keylen: 64,
    maxmem: 64 * 1024 * 1024
};


// Used when username does not exist
// so response time does not reveal it.
const DUMMY_HASH =
    "scrypt$16384$8$1$AAAAAAAAAAAAAAAAAAAAAA==$" +
    Buffer.alloc(64).toString("base64");


function hashPassword(
    password,
    cb
) {
    const salt =
        crypto.randomBytes(16);

    crypto.scrypt(
        password,
        salt,
        SCRYPT.keylen,
        {
            N: SCRYPT.N,
            r: SCRYPT.r,
            p: SCRYPT.p,
            maxmem: SCRYPT.maxmem
        },
        function (err, key) {

            if (err) {
                return cb(err);
            }

            cb(
                null,
                [
                    "scrypt",
                    SCRYPT.N,
                    SCRYPT.r,
                    SCRYPT.p,
                    salt.toString("base64"),
                    key.toString("base64")
                ].join("$")
            );
        }
    );
}


function verifyPassword(
    password,
    stored,
    cb
) {
    const parts =
        String(stored || "")
            .split("$");

    if (
        parts.length !== 6 ||
        parts[0] !== "scrypt"
    ) {
        return cb(false);
    }

    const N = Number(parts[1]);
    const r = Number(parts[2]);
    const p = Number(parts[3]);

    const salt =
        Buffer.from(
            parts[4],
            "base64"
        );

    const expected =
        Buffer.from(
            parts[5],
            "base64"
        );

    crypto.scrypt(
        String(password),
        salt,
        expected.length,
        {
            N: N,
            r: r,
            p: p,
            maxmem: SCRYPT.maxmem
        },
        function (err, key) {

            cb(
                !err &&
                key.length === expected.length &&
                crypto.timingSafeEqual(
                    key,
                    expected
                )
            );
        }
    );
}


function sha256(value) {
    return crypto
        .createHash("sha256")
        .update(String(value))
        .digest("hex");
}


// ---- end password helpers ----


// Verify password against stored scrypt hash;
// on success create server-side session.
// Output 1 → insert session
// Output 2 → response
// Output 3 → audit failed attempt.

const login = msg._login;

delete msg._login;

const row =
    Array.isArray(msg.payload)
        ? msg.payload[0]
        : null;


verifyPassword(
    login.password,
    row
        ? row.password_hash
        : DUMMY_HASH,

    function (valid) {

        const attempts =
            flow.get("loginAttempts") || {};


        if (
            !row ||
            !valid ||
            row.role !== "admin"
        ) {

            const now = Date.now();

            const rec =
                attempts[login.ip] ||
                {
                    count: 0,
                    first: now
                };

            rec.count += 1;


            if (
                rec.count >=
                CFG.auth.maxFailedLogins
            ) {

                rec.lockedUntil =
                    now +
                    CFG.auth.lockoutMinutes *
                    60000;

                rec.count = 0;
                rec.first = now;
            }


            attempts[login.ip] = rec;

            flow.set(
                "loginAttempts",
                attempts
            );


            node.send([
                null,

                fail(
                    msg,
                    401,
                    "Username atau password salah.",
                    "INVALID_CREDENTIALS"
                ),

                auditMsg(
                    row
                        ? row.id
                        : null,

                    "LOGIN_FAILED",

                    "username: " +
                    login.username.slice(0, 64),

                    msg.req
                )
            ]);

            node.done();

            return;
        }


        delete attempts[login.ip];

        flow.set(
            "loginAttempts",
            attempts
        );


        const token =
            crypto.randomBytes(32)
                .toString("base64url");


        delete row.password_hash;


        msg._user =
            publicUser(row);

        msg._token =
            token;


        msg.topic =
            "INSERT INTO user_sessions " +
            "(user_id, token_hash, created_at, expires_at, last_seen_at, user_agent) " +
            "VALUES (?, ?, UTC_TIMESTAMP(), " +
            "DATE_ADD(UTC_TIMESTAMP(), INTERVAL ? HOUR), " +
            "UTC_TIMESTAMP(), ?)";


        msg.payload = [
            row.id,
            sha256(token),
            CFG.auth.sessionTtlHours,
            String(
                msg.req.headers["user-agent"] || ""
            ).slice(0, 255)
        ];


        node.send([
            msg,
            null,
            null
        ]);

        node.done();
    }
);

return null;

