// WITA DATE HELPER
// ============================================================

// "YYYY-MM-DD" (WITA calendar date) -> Date of 00:00 WITA
function witaMidnight(dateStr) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
        return null;
    }

    const d = new Date(
        dateStr + "T00:00:00+08:00"
    );

    if (isNaN(d.getTime())) {
        return null;
    }

    // Reject rolled-over dates such as 2026-02-31
    const back = new Date(
        d.getTime() + 8 * 60 * 60 * 1000
    ).toISOString().slice(0, 10);

    return back === dateStr ? d : null;
}


