    value,
    fallback,
    min,
    max
) {
    const n = parseInt(
        value,
        10
    );

    if (!Number.isFinite(n)) {
        return fallback;
    }

    return Math.min(
        max,
        Math.max(min, n)
    );
}


function numOrNull(v) {
    if (
        v === null ||
        v === undefined
    ) {
        return null;
    }

    const n = Number(v);

    return Number.isFinite(n)
        ? n
        : null;
}


