// ============================================================
// QUERY FILTERS
// ============================================================

function parseFilters(q) {
    q = q || {};

    const where = [];
    const params = [];
    const applied = {};

    const from = q.from
        ? witaMidnight(String(q.from))
        : null;

    const to = q.to
        ? witaMidnight(String(q.to))
        : null;

    if (q.from && !from) {
        return {
            error: "Tanggal awal tidak valid (format YYYY-MM-DD)."
        };
    }

    if (q.to && !to) {
        return {
            error: "Tanggal akhir tidak valid (format YYYY-MM-DD)."
        };
    }

    if (from && to && from > to) {
        return {
            error: "Tanggal awal tidak boleh setelah tanggal akhir."
        };
    }


    // water_quality.timestamp sudah WITA
    if (from) {
        where.push("timestamp >= ?");
        params.push(
            String(q.from) + " 00:00:00"
        );
        applied.from = String(q.from);
    }

    if (to) {
        const nextDay = new Date(
            to.getTime() + 86400000
        );

        const nextDayWita =
            nextDay.toISOString().slice(0, 10);

        where.push("timestamp < ?");
        params.push(
            nextDayWita + " 00:00:00"
        );
        applied.to = String(q.to);
    }


    // ========================================================
    // SESSION FILTER
    // ========================================================

    if (q.session && q.session !== "all") {

        const names =
            CFG.sessions
                .map(function (s) {
                    return s.name;
                })
                .concat(
                    CFG.outsideSessionLabel
                );

        if (names.indexOf(q.session) === -1) {
            return {
                error: "Sesi tidak dikenal."
            };
        }

        where.push(
            "(" +
            sessionCaseSql("timestamp") +
            ") = ?"
        );

        params.push(q.session);
        applied.session = q.session;
    }


    // ========================================================
    // QUALITY FILTER
    // ========================================================

    if (q.quality && q.quality !== "all") {

        if (
            ["GOOD", "WARNING", "DANGER"]
                .indexOf(q.quality) === -1
        ) {
            return {
                error: "Kategori kualitas tidak dikenal."
            };
        }

        where.push(
            "water_quality = ?"
        );

        params.push(q.quality);
        applied.quality = q.quality;
    }


    // ========================================================
    // SEARCH
    // ========================================================

    const search =
        typeof q.search === "string"
            ? q.search.trim().slice(0, 50)
            : "";

    if (search) {

        const like =
            "%" +
            search.replace(
                /[\\%_]/g,
                function (c) {
                    return "\\" + c;
                }
            ) +
            "%";

        where.push(
            "(DATE_FORMAT(timestamp, '%Y-%m-%d %H:%i:%s') LIKE ?" +
            " OR sensor_status LIKE ?" +
            " OR water_quality LIKE ?" +
            " OR (" +
            sessionCaseSql("timestamp") +
            ") LIKE ?)"
        );

        params.push(
            like,
            like,
            like,
            like
        );

        applied.search = search;
    }


    return {
        where:
            where.length
                ? "WHERE " + where.join(" AND ")
                : "",

        params: params,

        applied: applied
    };
}


