// ============================================================
// PUT /api/admin/profile/photo
// ============================================================

// Body:
// {
//     image: "data:image/...;base64,..."
// }
//
// Dashboard resizes photo to 256×256 before upload.
// Server still validates type, size and file signature.
//
// Output 1 → UPDATE
// Output 2 → error

const MAX_BYTES = 400 * 1024;

const body =
    msg.payload &&
        typeof msg.payload === "object"
        ? msg.payload
        : {};


// ============================================================
// VALIDATE DATA URL
// ============================================================

const match =
    typeof body.image === "string"
        ? /^data:image\/(jpeg|png|webp);base64,([A-Za-z0-9+/]+={0,2})$/
            .exec(body.image)
        : null;


if (!match) {
    return [
        null,
        fail(
            msg,
            400,
            "Format foto harus JPG, PNG, atau WebP.",
            "INVALID_IMAGE"
        )
    ];
}


// ============================================================
// DECODE IMAGE
// ============================================================

const bytes =
    Buffer.from(
        match[2],
        "base64"
    );


if (
    bytes.length === 0 ||
    bytes.length > MAX_BYTES
) {
    return [
        null,
        fail(
            msg,
            413,
            "Ukuran foto terlalu besar (maksimal 400 KB setelah diperkecil).",
            "IMAGE_TOO_LARGE"
        )
    ];
}


// ============================================================
// FILE SIGNATURE CHECK
// ============================================================

const signatures = {

    jpeg:
        bytes[0] === 0xff &&
        bytes[1] === 0xd8 &&
        bytes[2] === 0xff,

    png:
        bytes
            .slice(0, 8)
            .equals(
                Buffer.from([
                    0x89,
                    0x50,
                    0x4e,
                    0x47,
                    0x0d,
                    0x0a,
                    0x1a,
                    0x0a
                ])
            ),

    webp:
        bytes
            .slice(0, 4)
            .toString("ascii") === "RIFF" &&
        bytes
            .slice(8, 12)
            .toString("ascii") === "WEBP"
};


if (!signatures[match[1]]) {
    return [
        null,
        fail(
            msg,
            400,
            "File bukan gambar yang valid.",
            "INVALID_IMAGE"
        )
    ];
}


// ============================================================
// PREPARE UPDATE
// ============================================================

msg._action =
    "PHOTO_UPLOAD";

msg._auditDetail =
    match[1] +
    ", " +
    bytes.length +
    " bytes";


// IMPORTANT:
// users.updated_at tetap UTC.
msg.topic =
    "UPDATE users " +
    "SET profile_photo = ?, " +
    "updated_at = UTC_TIMESTAMP() " +
    "WHERE id = ?";

msg.payload = [
    body.image,
    msg.user.id
];

return [
    msg,
    null
];

// DELETE /api/admin/profile/photo — back to the default avatar.
msg._action = "PHOTO_REMOVE";
msg.topic = "UPDATE users SET profile_photo = NULL, updated_at = UTC_TIMESTAMP() WHERE id = ?";
msg.payload = [msg.user.id];
return msg;

