// SESSION
// ============================================================

// water_quality.timestamp sudah WITA.
// Jadi tidak perlu DATE_ADD +8 jam lagi.
function sessionCaseSql(col) {
    const hour = "HOUR(" + col + ")";

    return "CASE " +
        CFG.sessions.map(function (s) {
            return "WHEN " +
                hour +
                " >= " +
                s.startHour +
                " AND " +
                hour +
                " < " +
                s.endHour +
                " THEN '" +
                s.name +
                "'";
        }).join(" ") +
        " ELSE '" +
        CFG.outsideSessionLabel +
        "' END";
}


