// ============================================================
// POST /api/admin/password
// ============================================================

// Validate input, then load the current password hash.
//
// Output 1 → SELECT
// Output 2 → validation error response.

if (!CFG) {
    return notReady(1);
}

const body =
    msg.payload &&
    typeof msg.payload === "object"
        ? msg.payload
        : {};

const current =
    typeof body.current_password === "string"
        ? body.current_password
        : "";

const next =
    typeof body.new_password === "string"
        ? body.new_password
        : "";

const confirm =
    typeof body.confirm_password === "string"
        ? body.confirm_password
        : "";

const min =
    CFG.auth.minPasswordLength;


// ============================================================
// VALIDATION
// ============================================================

if (!current || !next || !confirm) {
    return [
        null,
        fail(
            msg,
            400,
            "Semua kolom password wajib diisi.",
            "INVALID_INPUT"
        )
    ];
}


if (next !== confirm) {
    return [
        null,
        fail(
            msg,
            400,
            "Konfirmasi password baru tidak sama.",
            "PASSWORD_MISMATCH"
        )
    ];
}


if (
    next.length < min ||
    next.length > 128
) {
    return [
        null,
        fail(
            msg,
            400,
            "Password baru minimal " +
            min +
            " karakter (maksimal 128).",
            "PASSWORD_TOO_SHORT"
        )
    ];
}


if (next === current) {
    return [
        null,
        fail(
            msg,
            400,
            "Password baru harus berbeda dari password saat ini.",
            "PASSWORD_UNCHANGED"
        )
    ];
}


// ============================================================
// LOAD CURRENT HASH
// ============================================================

msg._pw = {
    current: current,
    next: next
};

msg.topic =
    "SELECT password_hash " +
    "FROM users " +
    "WHERE id = ?";

msg.payload = [
    msg.user.id
];

return [
    msg,
    null
];

