// ============================================================
// PASSWORD HASHING HELPERS
// ============================================================

// Requires the "crypto" module in Setup.
//
// Format:
// scrypt$N$r$p$<salt base64>$<key base64>

const SCRYPT = {
    N: 16384,
    r: 8,
    p: 1,
    keylen: 64,
    maxmem: 64 * 1024 * 1024
};


// Used when username/user does not exist.
// Helps avoid revealing existence through response timing.
const DUMMY_HASH =
    "scrypt$16384$8$1$AAAAAAAAAAAAAAAAAAAAAA==$" +
    Buffer.alloc(64).toString("base64");


function hashPassword(password, cb) {

    const salt =
        crypto.randomBytes(16);

    crypto.scrypt(
        password,
        salt,
        SCRYPT.keylen,
        {
            N: SCRYPT.N,
            r: SCRYPT.r,
            p: SCRYPT.p,
            maxmem: SCRYPT.maxmem
        },
        function (err, key) {

            if (err) {
                return cb(err);
            }

            cb(
                null,
                [
                    "scrypt",
                    SCRYPT.N,
                    SCRYPT.r,
                    SCRYPT.p,
                    salt.toString("base64"),
                    key.toString("base64")
                ].join("$")
            );
        }
    );
}


function verifyPassword(password, stored, cb) {

    const parts =
        String(stored || "").split("$");

    if (
        parts.length !== 6 ||
        parts[0] !== "scrypt"
    ) {
        return cb(false);
    }

    const N = Number(parts[1]);
    const r = Number(parts[2]);
    const p = Number(parts[3]);

    const salt =
        Buffer.from(
            parts[4],
            "base64"
        );

    const expected =
        Buffer.from(
            parts[5],
            "base64"
        );

    crypto.scrypt(
        String(password),
        salt,
        expected.length,
        {
            N: N,
            r: r,
            p: p,
            maxmem: SCRYPT.maxmem
        },
        function (err, key) {

            cb(
                !err &&
                key.length === expected.length &&
                crypto.timingSafeEqual(
                    key,
                    expected
                )
            );
        }
    );
}


function sha256(value) {
    return crypto
        .createHash("sha256")
        .update(String(value))
        .digest("hex");
}


// ---- end password helpers ----


// ============================================================
// VERIFY CURRENT PASSWORD
// ============================================================

const pw = msg._pw;

delete msg._pw;

const row =
    Array.isArray(msg.payload)
        ? msg.payload[0]
        : null;


verifyPassword(
    pw.current,
    row
        ? row.password_hash
        : DUMMY_HASH,
    function (valid) {

        if (!row || !valid) {

            node.send([
                null,
                fail(
                    msg,
                    400,
                    "Password saat ini salah.",
                    "WRONG_PASSWORD"
                )
            ]);

            node.done();

            return;
        }


        // ====================================================
        // CREATE NEW HASH
        // ====================================================

        hashPassword(
            pw.next,
            function (err, hash) {

                if (err) {

                    node.send([
                        null,
                        fail(
                            msg,
                            500,
                            "Gagal mengubah password.",
                            "HASH_FAILED"
                        )
                    ]);

                    node.done();

                    return;
                }


                // ====================================================
                // UPDATE PASSWORD
                // ====================================================

                msg._action =
                    "PASSWORD_CHANGE";

                // users.updated_at tetap UTC.
                msg.topic =
                    "UPDATE users " +
                    "SET password_hash = ?, " +
                    "updated_at = UTC_TIMESTAMP() " +
                    "WHERE id = ?";

                msg.payload = [
                    hash,
                    msg.user.id
                ];

                node.send([
                    msg,
                    null
                ]);

                node.done();
            }
        );
    }
);

return null;

// After a password change, sign out every other session of this account.
msg._auditDetail = "other sessions revoked";
msg.topic = "DELETE FROM user_sessions WHERE user_id = ? AND id <> ?";
msg.payload = [msg.user.id, msg._sessionId];
return msg;

