// "YYYY-MM-DD" (WITA calendar date) -> Date object
function witaMidnight(dateStr) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return null;

    const d = new Date(
        dateStr + "T00:00:00" + CFG.utcOffset
    );

    if (isNaN(d.getTime())) return null;

    // Reject invalid rolled-over dates such as 2026-02-31
    const back = new Date(
        d.getTime() + CFG.utcOffsetMinutes * 60000
    ).toISOString().slice(0, 10);

    return back === dateStr ? d : null;
}

