// water_quality.timestamp is stored in MySQL as WITA (UTC+8) DATETIME.
// Water-quality API timestamps are returned with +08:00.
// User/auth/audit timestamps remain UTC and are returned as Z unless
// their storage is separately verified as WITA.
const CFG = global.get("aquasense");

function reply(m, status, body) {
    m.statusCode = status;
    m.headers = Object.assign({}, m.headers, {
        "Content-Type": "application/json; charset=utf-8",
        "Cache-Control": "no-store",
        "X-Content-Type-Options": "nosniff",
    });
    m.payload = body;
    m._responded = true;
    return m;
}

function ok(m, data) {
    return reply(m, 200, {
        success: true,
        data: data
    });
}

function fail(m, status, message, code) {
    return reply(m, status, {
        success: false,
        message: message,
        code: code || null
    });
}

function pad(n) {
    return String(n).padStart(2, "0");
}

// "YYYY-MM-DD" (WITA calendar date) -> Date of 00:00 WITA
function witaMidnight(dateStr) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
        return null;
    }

    const d = new Date(
        dateStr + "T00:00:00+08:00"
    );

    if (isNaN(d.getTime())) {
        return null;
    }

    // Reject rolled-over dates such as 2026-02-31
    const back = new Date(
        d.getTime() + 8 * 60 * 60 * 1000
    ).toISOString().slice(0, 10);

    return back === dateStr ? d : null;
}

// water_quality.timestamp is already WITA,
// therefore do NOT add +8 hours here.
function sessionCaseSql(col) {
    const hour = "HOUR(" + col + ")";

    return "CASE " +
        CFG.sessions.map(function (s) {
            return "WHEN " +
                hour +
                " >= " + s.startHour +
                " AND " +
                hour +
                " < " + s.endHour +
                " THEN '" +
                s.name +
                "'";
        }).join(" ") +
        " ELSE '" +
        CFG.outsideSessionLabel +
        "' END";
}

function readingColumns() {
    return "id, device_id, " +
        "DATE_FORMAT(timestamp, '%Y-%m-%dT%H:%i:%s+08:00') AS timestamp, " +
