// ---- health composition (prepended to "Health: respond" and the API error handler) ----

// LIVE requires a recent VALID reading stored by the pipeline —
// not just a reachable API or an open WebSocket.
function buildHealth(dbRow, dbError) {
    const cfg =
        global.get("aquasense") || {};

    const rt =
        global.get("aquasenseRuntime") || {};

    const now = Date.now();

    let latestAt =
        dbRow && dbRow.latest_ts
            ? dbRow.latest_ts
            : null;

    let source =
        latestAt
            ? "database"
            : null;

    if (dbError && rt.lastValidAt) {
        // MySQL is down but Node-RED still processed readings in memory.
        latestAt =
            new Date(
                rt.lastValidAt
            ).toISOString();

        source = "node-red";
    }

    const age =
        latestAt
            ? Math.max(
                0,
                Math.round(
                    (
                        now -
                        Date.parse(latestAt)
                    ) / 1000
                )
            )
            : null;

    const threshold =
        cfg.freshnessThresholdSeconds || 180;

    return {
        server_time:
            new Date(now).toISOString(),

        api: {
            status: "ok"
        },

        node_red: {
            status: "running",
            started_at:
                rt.startedAt || null
        },

        database:
            dbError
                ? {
                    status: "unreachable"
                }
                : {
                    status: "connected"
                },

        mqtt: {
            status:
                rt.mqttStatus || "unknown",

            last_message_at:
                rt.lastMqttAt
                    ? new Date(
                        rt.lastMqttAt
                    ).toISOString()
                    : null,
        },

        latest_reading_at:
            latestAt,

        latest_reading_source:
            source,

        data_age_seconds:
            age,

        freshness:
            latestAt === null
                ? "none"
                : age <= threshold
                    ? "fresh"
                    : "stale",

        freshness_threshold_seconds:
            threshold,

        sampling_interval_seconds:
            cfg.samplingIntervalSeconds || null,
    };
}

