// GET /api/water/series?range=15m|1h|24h|all|custom&from=YYYY-MM-DD&to=YYYY-MM-DD&max=N
// Stored readings for the live charts, oldest → newest.
//
// water_quality.timestamp is written with MySQL NOW() by "Prepare MySQL" and
// holds WITA (UTC+8), so the relative ranges compare against NOW() of the
// same connection and custom dates are WITA calendar days (inclusive).
// Self-contained (no shared prelude). Output 1 → MySQL, output 2 → response.
function bad(message) {
    msg.statusCode = 400;
    msg.headers = { "Cache-Control": "no-store" };
    msg.payload = { success: false, message: message, code: "BAD_REQUEST" };
    return [null, msg];
}
function validDate(s) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
    const d = new Date(s + "T00:00:00Z");
    return !isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s;
}

const q = (msg.req && msg.req.query) || {};
const RANGES = { "15m": 15, "1h": 60, "24h": 1440 };
const range = String(q.range || "1h");
const max = Math.min(Math.max(parseInt(q.max, 10) || 1500, 100), 5000);
const where = [];
const params = [];

if (RANGES[range]) {
    where.push("timestamp >= NOW() - INTERVAL " + RANGES[range] + " MINUTE");
} else if (range === "custom") {
    const from = String(q.from || "");
    const to = String(q.to || "");
    if (!validDate(from) || !validDate(to)) return bad("Tanggal tidak valid (format YYYY-MM-DD).");
    if (from > to) return bad("Tanggal awal tidak boleh setelah tanggal akhir.");
    where.push("timestamp >= ?", "timestamp < DATE_ADD(?, INTERVAL 1 DAY)");
    params.push(from + " 00:00:00", to);
} else if (range !== "all") {
    return bad("Periode tidak dikenal.");
}

msg._series = { range: range, max: max, from: q.from || null, to: q.to || null };
msg.topic = "SELECT id, device_id, DATE_FORMAT(timestamp, '%Y-%m-%dT%H:%i:%s+08:00') AS timestamp, " +
    "ph_raw, ph_filtered, tds_raw, tds_filtered, turbidity_raw, turbidity_filtered, sensor_status, water_quality " +
    "FROM water_quality" + (where.length ? " WHERE " + where.join(" AND ") : "") +
    " ORDER BY timestamp ASC, id ASC LIMIT 200000";
msg.payload = params;
return [msg, null];

// Chart series response. When the period holds more rows than `max`, every
// k-th stored reading is returned (plus the newest one) — real measured
// points only, nothing averaged or interpolated. This thinning is for drawing
// only; the evaluation metrics (/api/water/metrics) always use every row.
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const s = msg._series || { max: 1500 };
const num = function (v) {
    if (v === null || v === undefined || v === "") return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
};

const stride = rows.length > s.max ? Math.ceil(rows.length / s.max) : 1;
const out = [];
for (let i = 0; i < rows.length; i++) {
    if (i % stride !== 0 && i !== rows.length - 1) continue;
    const r = rows[i];
    out.push({
        id: r.id,
        device_id: r.device_id,
        timestamp: r.timestamp,
        ph_raw: num(r.ph_raw), ph_filtered: num(r.ph_filtered),
        tds_raw: num(r.tds_raw), tds_filtered: num(r.tds_filtered),
        turbidity_raw: num(r.turbidity_raw), turbidity_filtered: num(r.turbidity_filtered),
        sensor_status: r.sensor_status,
        water_quality: r.water_quality,
    });
}

msg.statusCode = 200;
msg.headers = { "Cache-Control": "no-store" };
msg.payload = {
    success: true,
    data: {
        range: s.range,
        from: s.from,
        to: s.to,
        total: rows.length,
        returned: out.length,
        stride: stride,
        truncated: rows.length >= 200000,
        server_time: new Date().toISOString(),
        rows: out,
    },
};
delete msg._series;
return msg;

// GET /api/water/metrics?from=YYYY-MM-DD&to=YYYY-MM-DD (WITA days, inclusive;
// both omitted = every stored reading).
//
// Kalman Filter evaluation over EVERY stored row of the period (never the
