const q = (msg.req && msg.req.query) || {};
const from = q.from ? String(q.from) : null;
const to = q.to ? String(q.to) : null;
if (from && !validDate(from)) return bad("Tanggal awal tidak valid (format YYYY-MM-DD).");
if (to && !validDate(to)) return bad("Tanggal akhir tidak valid (format YYYY-MM-DD).");
if (from && to && from > to) return bad("Tanggal awal tidak boleh setelah tanggal akhir.");

const where = [];
const params = [];
if (from) { where.push("timestamp >= ?"); params.push(from + " 00:00:00"); }
if (to) { where.push("timestamp < DATE_ADD(?, INTERVAL 1 DAY)"); params.push(to); }

const PARAMS = {
    ph: "(ph_raw IS NOT NULL AND ph_filtered IS NOT NULL AND ph_raw BETWEEN 0 AND 14 AND ph_filtered BETWEEN 0 AND 14)",
    tds: "(tds_raw IS NOT NULL AND tds_filtered IS NOT NULL AND tds_raw >= 0 AND tds_filtered >= 0)",
    turbidity: "(turbidity_raw IS NOT NULL AND turbidity_filtered IS NOT NULL AND turbidity_raw >= 0 AND turbidity_filtered >= 0)",
};
const cols = ["COUNT(*) AS total",
    "DATE_FORMAT(MIN(timestamp), '%Y-%m-%dT%H:%i:%s+08:00') AS first_at",
    "DATE_FORMAT(MAX(timestamp), '%Y-%m-%dT%H:%i:%s+08:00') AS last_at"];
Object.keys(PARAMS).forEach(function (k) {
    const ok = PARAMS[k];
    const raw = k + "_raw";
    const f = k + "_filtered";
    cols.push(
        "SUM(CASE WHEN " + ok + " THEN 1 ELSE 0 END) AS " + k + "_n",
        "STDDEV_SAMP(CASE WHEN " + ok + " THEN " + raw + " END) AS " + k + "_sd_raw",
        "STDDEV_SAMP(CASE WHEN " + ok + " THEN " + f + " END) AS " + k + "_sd_filtered",
        "AVG(CASE WHEN " + ok + " THEN " + raw + " END) AS " + k + "_mean_raw",
        "AVG(CASE WHEN " + ok + " THEN " + f + " END) AS " + k + "_mean_filtered",
        "AVG(CASE WHEN " + ok + " THEN ABS(" + raw + " - " + f + ") END) AS " + k + "_mad_vs_raw",
        "SQRT(AVG(CASE WHEN " + ok + " THEN POW(" + raw + " - " + f + ", 2) END)) AS " + k + "_rmsd_vs_raw"
    );
});

const maxGap = ((global.get("aquasense") || {}).freshnessThresholdSeconds) || 180;
const sources = ["(SELECT " + cols.join(", ") + " FROM water_quality" + (where.length ? " WHERE " + where.join(" AND ") : "") + ") a"];
let allParams = params.slice();
Object.keys(PARAMS).forEach(function (k) {
    const raw = k + "_raw";
    const f = k + "_filtered";
    sources.push("(SELECT COUNT(*) AS " + k + "_steps, " +
        "AVG(ABS(" + raw + " - prev_raw)) AS " + k + "_fluct_raw, " +
        "AVG(ABS(" + f + " - prev_filtered)) AS " + k + "_fluct_filtered FROM (" +
        "SELECT timestamp, CAST(" + raw + " AS DOUBLE) AS " + raw + ", CAST(" + f + " AS DOUBLE) AS " + f + ", " +
        "CAST(LAG(" + raw + ") OVER w AS DOUBLE) AS prev_raw, CAST(LAG(" + f + ") OVER w AS DOUBLE) AS prev_filtered, LAG(timestamp) OVER w AS prev_ts " +
        "FROM water_quality WHERE " + where.concat(PARAMS[k]).join(" AND ") + " " +
        "WINDOW w AS (PARTITION BY device_id ORDER BY timestamp, id)) s " +
        "WHERE prev_ts IS NOT NULL AND TIMESTAMPDIFF(SECOND, prev_ts, timestamp) <= " + Number(maxGap) + ") " + k);
    allParams = allParams.concat(params);
});

msg._metrics = { from: from, to: to, maxGap: maxGap };
msg.topic = "SELECT * FROM " + sources.join(" CROSS JOIN ");
msg.payload = allParams;
return [msg, null];

// Evaluation metrics response (see "Metrics: query").
//   SD reduction (%) = (SD raw − SD filtered) / SD raw × 100
// It is null when SD raw is missing or 0 (no division by zero).
//   Fluctuation reduction (%) = (fluct raw − fluct filtered) / fluct raw × 100
// with fluct = mean absolute change between consecutive readings; null when
// there is no valid step or fluct raw is 0.
// mad_vs_raw / rmsd_vs_raw compare filtered with RAW — a measure of how far
// the filter moved the signal, NOT accuracy: no independent reference
// (calibrated instrument / laboratory) is stored, so accuracy MAE/RMSE
// against ground truth is reported as unavailable.
const r = (Array.isArray(msg.payload) && msg.payload[0]) || {};
const m = msg._metrics || {};
const num = function (v) {
    if (v === null || v === undefined) return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
};
const total = num(r.total) || 0;

const parameters = {};
["ph", "tds", "turbidity"].forEach(function (k) {
    const n = num(r[k + "_n"]) || 0;
    const sdRaw = num(r[k + "_sd_raw"]);
    const sdFiltered = num(r[k + "_sd_filtered"]);
    let sdReduction = null;
    let note = null;
    if (n < 2) note = "Kurang dari 2 sampel valid";
    else if (sdRaw === null || sdFiltered === null) note = "SD tidak dapat dihitung";
    else if (sdRaw === 0) note = "SD raw = 0 (tidak ada variasi), reduksi tidak terdefinisi";
    else sdReduction = ((sdRaw - sdFiltered) / sdRaw) * 100;
    const steps = num(r[k + "_steps"]) || 0;
    const fluctRaw = steps ? num(r[k + "_fluct_raw"]) : null;
    const fluctFiltered = steps ? num(r[k + "_fluct_filtered"]) : null;
    let fluctReduction = null;
    let fluctNote = null;
    if (!steps) fluctNote = "Tidak ada pasangan pembacaan berurutan";
    else if (fluctRaw === null || fluctFiltered === null) fluctNote = "Fluktuasi tidak dapat dihitung";
    else if (fluctRaw === 0) fluctNote = "Fluktuasi raw = 0, reduksi tidak terdefinisi";
    else fluctReduction = ((fluctRaw - fluctFiltered) / fluctRaw) * 100;
    parameters[k] = {
        valid_samples: n,
        excluded_samples: Math.max(0, total - n),
        sd_raw: sdRaw,
        sd_filtered: sdFiltered,
        sd_reduction_pct: sdReduction,
        note: note,
        mean_raw: num(r[k + "_mean_raw"]),
        mean_filtered: num(r[k + "_mean_filtered"]),
        mad_vs_raw: num(r[k + "_mad_vs_raw"]),
        rmsd_vs_raw: num(r[k + "_rmsd_vs_raw"]),
        fluct_steps: steps,
        fluct_raw: fluctRaw,
        fluct_filtered: fluctFiltered,
        fluct_reduction_pct: fluctReduction,
        fluct_note: fluctNote,
    };
});

msg.statusCode = 200;
msg.headers = { "Cache-Control": "no-store" };
msg.payload = {
    success: true,
    data: {
        filters: { from: m.from || null, to: m.to || null },
        total_rows: total,
        first_at: r.first_at || null,
        last_at: r.last_at || null,
        computed_at: new Date().toISOString(),
        sd_method: "sample (n-1), MySQL STDDEV_SAMP",
        pairing: "same record (raw and filtered of one water_quality row)",
        fluct_method: "mean |x[i] - x[i-1]|, consecutive valid readings per device ordered by timestamp, gap <= " + m.maxGap + " s",
        ground_truth_available: false,
        parameters: parameters,
    },
};
delete msg._metrics;
return msg;

// POST /api/admin/telegram/test (behind the auth guard) — sends one test
// message through the SAME path as real notifications (Telegram sender →
// retry → notification_log, event TEST), so delivery from Node-RED can be
// verified without waiting for a water-quality change. TEST rows never affect
// the de-duplication state. At most one test per 30 s.
// Output 1 → link to the Telegram sender, output 2 → HTTP response.
const now = Date.now();
const last = global.get("aquasenseTelegramTestAt") || 0;
msg.headers = { "Cache-Control": "no-store" };
if (now - last < 30000) {
    msg.statusCode = 429;
    msg.payload = { success: false, message: "Tunggu " + Math.ceil((30000 - (now - last)) / 1000) + " detik sebelum mengirim pesan uji lagi.", code: "RATE_LIMITED" };
    return [null, msg];
}
global.set("aquasenseTelegramTestAt", now);

const waktu = new Date(now).toLocaleString("id-ID", {
    timeZone: "Asia/Makassar", day: "2-digit", month: "short", year: "numeric",
    hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false,
}) + " WITA";
const content = "💧 AQUASENSE BORIKAMASE\n\n🧪 Pesan uji dari Node-RED\nNotifikasi Telegram berfungsi.\n\n🕐 Waktu: " + waktu;

const out = {
    payload: { chatId: "YOUR_TELEGRAM_CHAT_ID", type: "message", content: content },
    notification: {
        test: true,
        events: ["TEST"],
        severity: "INFO",
        quality: null,
        previous_quality: null,
        sensor_status: null,
        reading_timestamp: new Date(now).toISOString(),
        attempt: 1,
        title: "Pesan uji",
        message: content,
    },
};

msg.statusCode = 202;
msg.payload = { success: true, data: { queued: true, message: "Pesan uji dikirim ke antrean. Hasilnya muncul di riwayat notifikasi." } };
return [out, msg];
